        clearInterval(timer.current);
        timer.current = null;
        saveSnapshot({ ...latest.current, output: target.current });
      }
    },
    []
  );

  const patch = useCallback((next: Partial<DemoSnapshot>) => {
    setSnap((s) => ({ ...s, ...next }));
  }, []);

